import{_ as t,a as r,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"List Returnable Orders","description":"","frontmatter":{"outline":false,"examples":[{"id":"returnable-orders","title":"List Returnable Orders","description":"The customer's orders a return can still be raised against — the list the New Request flow opens with.","query":"query {\\n  returnableOrders {\\n    id\\n    _id\\n    incrementId\\n    status\\n    statusLabel\\n    grandTotal\\n    formattedGrandTotal\\n    orderCurrencyCode\\n    paymentMethodTitle\\n    totalQtyOrdered\\n    totalReturnedQty\\n    returnableQty\\n    createdAt\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"returnableOrders\\": [\\n      {\\n        \\"id\\": \\"/api/shop/returnable_orders/41\\",\\n        \\"_id\\": 41,\\n        \\"incrementId\\": \\"41\\",\\n        \\"status\\": \\"completed\\",\\n        \\"statusLabel\\": \\"Completed\\",\\n        \\"grandTotal\\": 160.0,\\n        \\"formattedGrandTotal\\": \\"$160.00\\",\\n        \\"orderCurrencyCode\\": \\"USD\\",\\n        \\"paymentMethodTitle\\": \\"Cash On Delivery\\",\\n        \\"totalQtyOrdered\\": 3,\\n        \\"totalReturnedQty\\": 1,\\n        \\"returnableQty\\": 2,\\n        \\"createdAt\\": \\"2026-08-30 09:12:44\\"\\n      }\\n    ]\\n  }\\n}\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]},{"id":"returnable-orders-filtered","title":"Filter by Order Number","description":"Narrow the list to one order number, or to a status, and choose the sort.","query":"query ($incrementId: String, $sort: String, $order: String) {\\n  returnableOrders(incrementId: $incrementId, sort: $sort, order: $order) {\\n    _id\\n    incrementId\\n    status\\n    formattedGrandTotal\\n    returnableQty\\n    createdAt\\n  }\\n}\\n","variables":"{\\n  \\"incrementId\\": \\"41\\",\\n  \\"sort\\": \\"grand_total\\",\\n  \\"order\\": \\"desc\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"returnableOrders\\": [\\n      {\\n        \\"_id\\": 41,\\n        \\"incrementId\\": \\"41\\",\\n        \\"status\\": \\"completed\\",\\n        \\"formattedGrandTotal\\": \\"$160.00\\",\\n        \\"returnableQty\\": 2,\\n        \\"createdAt\\": \\"2026-08-30 09:12:44\\"\\n      }\\n    ]\\n  }\\n}\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/queries/list-returnable-orders.md","filePath":"api/graphql-api/shop/returns/queries/list-returnable-orders.md","lastUpdated":1789385991000}`),n={name:"api/graphql-api/shop/returns/queries/list-returnable-orders.md"};function o(s,e,i,l,c,h){return a(),r("div",null,e[0]||(e[0]=[d('<h1 id="list-returnable-orders" tabindex="-1">List Returnable Orders <a class="header-anchor" href="#list-returnable-orders" aria-label="Permalink to &quot;List Returnable Orders&quot;">​</a></h1><p>The authenticated customer&#39;s orders that can still start a return. This is the first step of a return: pick an order here, read its items with <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a>, then submit with <a href="/api/graphql-api/shop/returns/mutations/create-return.html">Create Return</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="this-query-returns-a-plain-list" tabindex="-1">This Query Returns a Plain List <a class="header-anchor" href="#this-query-returns-a-plain-list" aria-label="Permalink to &quot;This Query Returns a Plain List&quot;">​</a></h2><p><code>returnableOrders</code> is a list, not a Relay connection — a customer has few returnable orders, so the whole set comes back in one call. Select the fields directly as the examples do. Asking for <code>edges</code>, <code>node</code>, <code>pageInfo</code> or <code>totalCount</code> is a schema error, and the same is true of <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a>.</p><p>An empty list means the customer has nothing to return right now — show that rather than an error.</p><h2 id="when-an-order-appears" tabindex="-1">When an Order Appears <a class="header-anchor" href="#when-an-order-appears" aria-label="Permalink to &quot;When an Order Appears&quot;">​</a></h2><p>An order is listed while all of the following hold. They are evaluated per item, so one eligible item is enough to list the order.</p><ol><li><strong>The item was sold with returns allowed.</strong> Eligibility is captured when the order is placed, from the product type the store permits returns for. An item placed while returns were off never becomes returnable later.</li><li><strong>The return window is still open.</strong> Each item carries its own window, taken from the store&#39;s return period at the time of purchase, counted from the item&#39;s own date.</li><li><strong>Quantity is left.</strong> Everything already requested on that item is subtracted; once the whole quantity is covered, the order drops off the list.</li><li><strong>The order is in a usable state.</strong> Canceled, closed, fraud and pending-payment orders never appear.</li></ol><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>incrementId</code></td><td>String</td><td>Match the order number, partially.</td></tr><tr><td><code>status</code></td><td>String</td><td>Match the order status exactly, e.g. <code>completed</code> or <code>processing</code>.</td></tr><tr><td><code>sort</code></td><td>String</td><td><code>created_at</code> (default), <code>increment_id</code> or <code>grand_total</code>.</td></tr><tr><td><code>order</code></td><td>String</td><td><code>desc</code> (default) or <code>asc</code>.</td></tr></tbody></table><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>Resource IRI.</td></tr><tr><td><code>_id</code></td><td>Int</td><td>Order id — pass this as the order when listing items or creating the return.</td></tr><tr><td><code>incrementId</code></td><td>String</td><td>Order number as the customer sees it.</td></tr><tr><td><code>status</code></td><td>String</td><td>Order status.</td></tr><tr><td><code>statusLabel</code></td><td>String</td><td>Translated status, ready to display.</td></tr><tr><td><code>grandTotal</code></td><td>Float</td><td>Order total in the order&#39;s currency.</td></tr><tr><td><code>formattedGrandTotal</code></td><td>String</td><td>Total formatted in the order&#39;s currency.</td></tr><tr><td><code>orderCurrencyCode</code></td><td>String</td><td>Currency the order was placed in.</td></tr><tr><td><code>paymentMethodTitle</code></td><td>String</td><td>Payment method title, or <code>null</code> when the order has none recorded.</td></tr><tr><td><code>totalQtyOrdered</code></td><td>Int</td><td>Quantity across the order&#39;s returnable items.</td></tr><tr><td><code>totalReturnedQty</code></td><td>Int</td><td>Quantity already covered by returns.</td></tr><tr><td><code>returnableQty</code></td><td>Int</td><td>What is left — <code>totalQtyOrdered</code> minus <code>totalReturnedQty</code>.</td></tr><tr><td><code>createdAt</code></td><td>String</td><td>When the order was placed.</td></tr></tbody></table><p><code>returnableQty</code> is a whole-order figure for display. The per-item caps the server actually enforces come from <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a>.</p><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a> — the items of a chosen order, with the quantity caps</li><li><a href="/api/graphql-api/shop/returns/mutations/create-return.html">Create Return</a> — raise the return</li></ul>',17)]))}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
